<template>
  <view class="page">
    <!-- 轮播区域 -->
    <swiper
      class="custom-swiper"
      :indicator-dots="true"
      :autoplay="false"
      :interval="3000"
      :duration="500"
      :circular="true"
    >
      <!-- 轮播项1 -->
      <swiper-item>
        <view class="swiper-item" v-for="(item,i) in swiperList" :key="i" @tap="toDetail(item.id)">
             <view class="item-text">
            <!-- 第一行：赛事轮次和时间 -->
            <view class="match-header">
              <text class="match-round">{{item.league_name}}第{{item.round_no}}轮</text>
              <text class="match-date">{{item.race_date}}</text>
            </view>
            <text class="prediction-label">分析</text>
            <!-- 对阵信息 -->
            <view class="teams-container">
              <text class="team-name home">{{item.home_name}}</text>
              <text class="vs-separator">:</text>
              <text class="team-name away">{{item.visiting_name}}</text>
            </view>
            
            <!-- 预测信息 -->
            
            <view class="odds-container">
              <text class="odds home-odds">{{item.home_win_rate?item.home_win_rate.toFixed(2)*100:''}}</text>
              <text class="odds-separator">:</text>
              <text class="odds away-odds">{{item.visiting_win_rate?item.visiting_win_rate.toFixed(2)*100:''}}</text>
            </view>
          </view>
        </view>
      </swiper-item>
    </swiper>
  </view>
</template>

<script>
import {
getSwiper
} from "@/api/demo";
export default {
  name: "CustomCarouselPage",
  data() {
    return {
      swiperList:[]
    };
  },
  created(){
    this.getSwiperList();
  },
  methods: {
    toDetail(id){
      this.$router.push({
        path: `/pages/test/index`,
        query: {
          id
        }
      })
    },
    async getSwiperList(){
      const isApp = typeof plus !== 'undefined'; // HBuilderX基座特有对象
      const res = await getSwiper();
      this.swiperList =  res.data;
    },
  },
};
</script>

<style lang="scss" scoped>
.page {
  padding: 20rpx;
  position:fixed;
  left:0;
  top:0;
  margin:auto;
  z-index:9999;
  width: 100%;
  background: #fff;
.custom-swiper {
  width: 100%;
  height: 300rpx;
.swiper-item {
  width: 100%;
  height: 100%;
  background-color: #ffffff;
  border-radius: 16rpx;
  box-shadow: 0 4rpx 12rpx rgba(0, 0, 0, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  .item-text {
  width: 85%;
  height: 80%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
}
/* 第一行：赛事轮次和时间 */
.match-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
}
/* 预测信息 */
.prediction-label {
  font-size: 28rpx;
  font-weight: 500;
  margin: 10rpx 0;
  text-align: right;
  height: 44rpx;
  background-image: linear-gradient(to right, #ff0000, #00ff00, #0000ff);
  color: transparent;
  -webkit-background-clip: text;
  background-clip: text;
}
/* 对阵信息 */
.teams-container {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}
.odds-container {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  margin-bottom: 10rpx;
}

}
}
}













.team-name {
  font-size: 28rpx;
  font-weight: bold;
  padding: 0 30rpx;
  color:#444;
}

/* .home {
  color: #2c3e50;
}

.away {
  color: #2c3e50;
} */

.vs-separator {
  font-size: 36rpx;
  color: #95a5a6;
  font-weight: 500;
}




.odds {
  font-size: 32rpx;
  font-weight: bold;
  padding: 4rpx 40rpx;
  border-radius: 8rpx;
  color: #2c3e50;
}
.odds-separator {
  font-size: 32rpx;
  color: #2c3e50;
  padding: 0 15rpx;
}
.home-odds {
  color:#0f40f5;
}
.away-odds{
  color:#0f40f5;
}
</style>